test('Farm replant Service initial seed sum is mandatory before any harvest',async()=>{const f=await sequenceFixture({seeds:1});try{await assert.rejects(f.operations.prepareFarmHarvestSource(f.account,{...f.payload,replant:f.payload.targets.map(t=>({buildingId:t.buildingId,productId:'小麦'}))}),{code:'INVALID_PARAMETERS'});assert.equal(f.writes.length,0);assert.deepEqual(f.durable.list(f.account.id),[]);}finally{await f.closeSequence();}});
test('Farm replant Service consumed predecessor cannot authorize planting when the plot becomes empty again',async()=>{const f=await replantFixture({plots:1});try{const hp=f.prepared.graph.nodes[1].parameters,pp=f.prepared.graph.nodes.find(n=>n.id==='plant-0').parameters;assert.equal((await f.execute(await f.plan(hp))).finalStatus,'SUCCESS');assert.equal((await f.execute(await f.plan(pp))).finalStatus,'SUCCESS');f.raw.building[0].farm=empty('1农田').farm;const v=await f.operations.surveyModule(f.account,'farm',pp);assert.equal(v.view.candidates[0].blockedReason,'FARM_REPLANT_CONFIRMED_HARVEST_REQUIRED');await assert.rejects(f.plan(pp));assert.equal(f.writes.length,2);}finally{await f.closeSequence();}});
test('Farm replant Service restart loses original connection evidence and never restores a permit',async()=>{const f=await replantFixture({plots:1});try{const r=await f.runner.start(f.account.id,f.prepared.graph);assert.equal((await f.execute(r.plan)).finalStatus,'SUCCESS');const next=f.restart(),parameters=f.prepared.graph.nodes.find(n=>n.id==='plant-0').parameters,before=fs.readFileSync(f.file),v=await next.operations.surveyModule(next.account,'farm',parameters);assert.equal(v.view.candidates[0].executable,false);assert.deepEqual(fs.readFileSync(f.file),before);await assert.rejects(next.operations.plan(next.account,{module:'farm',mode:'Manual',parameters,selections:[v.view.candidates[0].actionId]}));assert.equal(f.writes.length,1);assert.equal(next.operations.workflowBudget(f.account.id),null);}finally{await f.closeSequence();}});
for(const step of ['harvest','plant'])test('Farm replant Service '+step+' refusal cannot be bypassed through the plain entry or a new connection',async()=>{const f=await replantFixture({plots:1});try{const plant=step==='plant';if(plant)assert.equal((await f.execute(await f.plan(f.prepared.graph.nodes[1].parameters))).finalStatus,'SUCCESS');const guarded=f.prepared.graph.nodes.find(n=>n.id===(plant?'plant-0':'harvest-0')).parameters,plain=plant?params('1农田'):{buildingId:'1农田',action:'harvest'},client=f.account.client;if(plant)client.sendWatch=async(n,b,o)=>{o.beforeDispatch?.();f.writes.push({name:n,body:b});return {status:'REJECTED'};};else{const request=client.request.bind(client);client.request=async(n,b,...args)=>{if(n!=='FarmHarvestRequest')return request(n,b,...args);args.at(-1)?.beforeDispatch?.();f.writes.push({name:n,body:b});throw Object.assign(Error('synthetic refusal'),{code:'REJECTED'});};}assert.equal((await f.execute(await f.plan(guarded))).finalStatus,'REJECTED');await assert.rejects(f.plan(plain),{code:'REJECTION_MEMORY_ACTIVE'});const next=f.restart(),v=await next.operations.surveyModule(next.account,'farm',plain);await assert.rejects(next.operations.plan(next.account,{module:'farm',mode:'Manual',parameters:plain,selections:[v.view.candidates[0].actionId]}),{code:'REJECTION_MEMORY_ACTIVE'});assert.equal(f.writes.length,plant?2:1);}finally{await f.closeSequence();}});
test('Farm replant Service original parent seed budget does not grow from later income',async()=>{const f=await replantFixture();try{f.prepared.graph.budget.resources[0].num=1;let r=await f.runner.start(f.account.id,f.prepared.graph);for(let i=0;i<3;i++){assert.equal((await f.execute(r.plan)).finalStatus,'SUCCESS');r=await f.runner.resume();}f.stock.set(seed,100);const record=await f.execute(r.plan);assert.equal(record.finalStatus,'NOT_EXECUTED');assert.equal(f.writes.length,3);assert.equal(f.stock.get(seed),100);assert.equal(reserved(record.runBudget),1);assert.notEqual((await f.runner.resume()).status,'COMPLETED');}finally{await f.closeSequence();}});

for(const step of [0,1])for(const dimension of ['account','player','world','generation','connection'])test('Farm replant Service dispatched '+(step?'plant':'harvest')+' late '+dimension+' change stays UNKNOWN',async()=>{const f=await replantFixture({plots:1});try{let r=await f.runner.start(f.account.id,f.prepared.graph);if(step){assert.equal((await f.execute(r.plan)).finalStatus,'SUCCESS');r=await f.runner.resume();}const change=value=>{if(dimension==='account')f.account.client.factContext.accountId='other';if(dimension==='player')f.account.player.playerId='2';if(dimension==='world')f.account.player.worldId=13;if(dimension==='generation')f.account.client.factContext.generation++;if(dimension==='connection')f.account.client.factContext.connectionId='other';return value;};if(step)f.account.client.onPlant=change;else f.account.client.onHarvest=change;assert.equal((await f.execute(r.plan)).finalStatus,'UNKNOWN');assert.equal(f.writes.length,step+1);assert.equal((await f.runner.resume()).status,'CANCELLED');const next=f.restart();assert.equal(next.operations.blocked(f.account.id),true);assert.equal(f.writes.length,step+1);}finally{await f.closeSequence();}});
test('Farm replant Service reverse plot order and distinct next crops debit only initial seed sums',async()=>{const f=await replantFixture({seeds:3});try{f.config.tables.FarmlandPlantCfg.data.push({id:'玉米',material:['玉米种子',2],time:1800,produceNum:5});f.stock.set('玉米种子',2);f.payload.targets.reverse();f.payload.replant=f.payload.targets.map((t,i)=>({buildingId:t.buildingId,productId:i?'小麦':'玉米'}));f.prepared=await f.operations.prepareFarmHarvestSource(f.account,f.payload);f.account.client.onPlant=result=>{if(f.writes.at(-1).body.args[0].productId==='玉米'){f.stock.set(seed,f.stock.get(seed)+1);f.stock.set('玉米种子',f.stock.get('玉米种子')-2);}return result;};assert.deepEqual(f.prepared.graph.budget.resources,[{id:'玉米种子',num:2},{id:seed,num:1}]);let r=await f.runner.start(f.account.id,f.prepared.graph);for(let i=0;i<4;i++){assert.equal((await f.execute(r.plan)).finalStatus,'SUCCESS');r=await f.runner.resume();}assert.equal(r.status,'COMPLETED');assert.deepEqual(f.writes.map(w=>w.body),[{buildingId:['2农田']},{args:[{buildingId:'2农田',productId:'玉米'}]},{buildingId:['1农田']},{args:[{buildingId:'1农田',productId:'小麦'}]}]);assert.equal(f.stock.get(seed),2);assert.equal(f.stock.get('玉米种子'),0);}finally{await f.closeSequence();}});
test('Farm replant Service missing second crop UID cannot borrow the confirmed first harvest',async()=>{const f=await replantFixture();try{f.prepared.graph.budget.uids.pop();let r=await f.runner.start(f.account.id,f.prepared.graph);for(let i=0;i<2;i++){assert.equal((await f.execute(r.plan)).finalStatus,'SUCCESS');r=await f.runner.resume();}await assert.rejects(f.execute(r.plan),{code:'RUN_BUDGET_INVALID'});assert.equal(f.writes.length,2);assert.equal(f.raw.building[1].farm.productId,'小麦');const history=f.durable.list(f.account.id);assert.equal(history.length,3);const rejected=history.find(row=>row.finalStatus==='NOT_EXECUTED');assert.ok(rejected);assert.equal(rejected.actions[0].requestStatus,'NOT_DISPATCHED');assert.equal(rejected.actions[0].result,'NOT_EXECUTED');}finally{await f.closeSequence();}});
test('Farm replant Service corrupted durable history after authorization cannot send a plant',async()=>{const f=await replantFixture({plots:1});try{assert.equal((await f.execute(await f.plan(f.prepared.graph.nodes[1].parameters))).finalStatus,'SUCCESS');const p=await f.plan(f.prepared.graph.nodes.find(n=>n.id==='plant-0').parameters),permit=f.authorize(p);fs.writeFileSync(f.file,'{');await assert.rejects(f.execute(p,permit));assert.equal(f.writes.length,1);assert.equal(fs.readFileSync(f.file,'utf8'),'{');}finally{await f.closeSequence();}});

for(const harvest of [false,true])for(const phase of ['before','after'])for(const alias of ['id','count'])
 test('farm shared inventory conflict '+alias+' '+phase+' '+(harvest?'harvest':'plant')+' preserves original authorization and UNKNOWN history',async()=>{
  const f=fixture({harvest});
  try{
   const p=await f.plan(),permit=f.authorize(p),request=f.account.client.request.bind(f.account.client);
   f.account.client.request=async(...args)=>{
    const value=await request(...args);
    if(args[0]==='AllItemRequest'&&(phase==='before'||f.writes.length)){
     const row=value.items.find(r=>r.itemId===seed);row[alias]=alias==='id'?'foreign-seed':99;
    }
    return value;
   };
   const run=await f.execute(p,permit);
   assert.equal(run.finalStatus,phase==='before'?'NOT_EXECUTED':'UNKNOWN');assert.equal(f.writes.length,phase==='before'?0:1);
   assert.equal(run.actions[0].dispatched,phase==='after');
   if(phase==='before'){assert.equal(reserved(run.runBudget),0);assert.equal(run.runBudget.reserved.uids.length,0);assert.equal(f.stock.get(seed),3);}
   else{
    assert.equal(run.actions[0].unresolvedWrite,true);assert.equal(run.actions[0].verification.status,'UNCONFIRMED');
    assert.equal(reserved(run.runBudget),harvest?0:1);assert.equal(run.runBudget.reserved.uids.length,harvest?1:0);
    const reopened=f.restart();assert.equal(reopened.operations.status(f.account.id).blocked,true);
    assert.equal(reopened.operations.executionMemory(f.account.id).events[0].status,'UNKNOWN');
    await assert.rejects(reopened.operations.plan(reopened.account,{module:'farm',mode:'Manual',selections:p.actions.map(r=>r.actionId),parameters:harvest?{buildingId:'1农田',action:'harvest'}:params('1农田')}),{code:'RECOVERY_UNCERTAIN'});
    assert.equal(f.writes.length,1);assert.equal(f.durable.list(f.account.id)[0].finalStatus,'UNKNOWN');
   }
  }finally{await f.cleanup();}
 });
